fn find_grade(name: Str) -> Option[Str] {
  if name == "Alex"   { return Some("A"); }
  if name == "Bailey" { return Some("B"); }
  if name == "Casey"  { return Some("C"); }
  return None;
}

fn get_grade_message(name: Str) -> Str {
  if let Some(grade) = find_grade(name) {
    return name + " got a " + grade + "!";
  }
  return "Student " + name + " not found.";
}

fn main() -> Int {
  io.println(get_grade_message("Alex"));
  io.println(get_grade_message("Bailey"));
  io.println(get_grade_message("Unknown"));
  return 0;
}
